// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 firstNumber,
        uint64 secondNumber,
        uint64 ts,
        uint256 bf,
        bytes32 h,
        uint64 seq,
        bytes32 bh,
        uint256 overhead,
        uint256 scalar
    ) public {
        vm.prank(DEPOSITOR);
        c.setL1BlockValues(firstNumber, ts, bf, h, seq, bh, overhead, scalar);

        vm.prank(DEPOSITOR);
        c.setL1BlockValues(secondNumber, ts, bf, h, seq, bh, overhead, scalar);

        assertTrue(c.number() == secondNumber);
    }
}
